import React, { useRef, useEffect, useState, useCallback } from "react";
import { useI18n } from "../i18n/I18nContext";
import { useReducedMotion } from "../hooks/useAnimations";

const IMG_FRONT = "data:image/png;base64,";
const IMG_RIGHT = "data:image/png;base64,";
const IMG_TOP = "data:image/png;base64,";

// Only 2 real high-quality angles available right now.
// Spin is clamped between them (0deg = Front, 90deg = Right) rather than
// wrapping a full 360 — Back/Left were removed for quality reasons and
// will extend the range again once better photos exist.
const SPIN_FRAMES = [
  { angle: 0, key: "front", img: IMG_FRONT },
  { angle: 90, key: "side", img: IMG_RIGHT },
];

// Non-rotational static views, selected only via thumbnail.
const STATIC_VIEWS = [
  { key: "top", img: IMG_TOP },
  { key: "bottom", img: null },
];

function clamp(v, lo, hi) {
  return Math.max(lo, Math.min(hi, v));
}

export default function ProductViewer() {
  const { t } = useI18n();
  const prefersReduced = useReducedMotion();
  const L = {
    front: t("product.viewer.front"),
    side: t("product.viewer.side"),
    top: t("product.viewer.top"),
    hint: t("product.viewer.hint"),
    range: t("product.viewer.range"),
    caption: t("product.viewer.caption"),
    pending: t("product.viewer.pending"),
  };
  const lRef = useRef(L);
  lRef.current = L;
  const containerRef = useRef(null);
  const thetaRef = useRef(0);
  const targetRef = useRef(0);
  const velocityRef = useRef(0);
  const draggingRef = useRef(false);
  const lastXRef = useRef(0);
  const lastTRef = useRef(0);
  const hoverActiveRef = useRef(false);
  const tiltXRef = useRef(0);
  const tiltXCurRef = useRef(0);
  const rafRef = useRef(null);
  const timeRef = useRef(0);

  const [mode, setMode] = useState("spin");
  const [staticKey, setStaticKey] = useState(null);
  const [staticOpacity, setStaticOpacity] = useState(0);

  const [display, setDisplay] = useState({ theta: 0, tiltX: 0, bob: 0, activeLabel: L.front });

  useEffect(() => {
    let lastTs = performance.now();
    const loop = (ts) => {
      const dt = Math.min((ts - lastTs) / 1000, 0.05);
      lastTs = ts;
      timeRef.current += dt;

      if (mode === "spin") {
        targetRef.current = clamp(targetRef.current, 0, 90);
        if (draggingRef.current) {
          thetaRef.current = targetRef.current;
        } else {
          velocityRef.current = 0;
          const delta = targetRef.current - thetaRef.current;
          thetaRef.current += delta * Math.min(dt * 6.5, 1);
        }
        thetaRef.current = clamp(thetaRef.current, 0, 90);
      }

      tiltXCurRef.current += (tiltXRef.current - tiltXCurRef.current) * Math.min(dt * 8, 1);
      const bob = prefersReduced ? 0 : Math.sin(timeRef.current * 1.15) * 9;

      const activeLabel =
        mode === "spin"
          ? thetaRef.current < 45
            ? lRef.current.front
            : lRef.current.side
          : staticKey === "top"
            ? lRef.current.top
            : lRef.current.front;

      setDisplay({ theta: thetaRef.current, tiltX: tiltXCurRef.current, bob, activeLabel });

      setStaticOpacity((prev) => {
        const target = mode === "static" ? 1 : 0;
        return prev + (target - prev) * Math.min(dt * 7, 1);
      });

      rafRef.current = requestAnimationFrame(loop);
    };
    rafRef.current = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(rafRef.current);
  }, [mode, staticKey, prefersReduced]);

  const handlePointerMove = useCallback((clientX, clientY) => {
    const el = containerRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const relX = (clientX - rect.left) / rect.width - 0.5;
    const relY = (clientY - rect.top) / rect.height - 0.5;

    if (draggingRef.current) {
      const now = performance.now();
      const dx = clientX - lastXRef.current;
      const dtms = Math.max(now - lastTRef.current, 1);
      const degPerPx = 0.35;
      targetRef.current = clamp(targetRef.current + dx * degPerPx, 0, 90);
      velocityRef.current = 0;
      lastXRef.current = clientX;
      lastTRef.current = now;
    } else if (hoverActiveRef.current && mode === "spin") {
      targetRef.current = clamp((relX + 0.5) * 90, 0, 90);
    }
    tiltXRef.current = -relY * 10;
  }, [mode]);

  const enterSpinMode = () => {
    if (mode !== "spin") {
      setMode("spin");
      setStaticKey(null);
    }
  };

  const onMouseMove = (e) => handlePointerMove(e.clientX, e.clientY);
  const onMouseEnter = () => (hoverActiveRef.current = true);
  const onMouseLeave = () => {
    hoverActiveRef.current = false;
    tiltXRef.current = 0;
  };
  const onMouseDown = (e) => {
    enterSpinMode();
    draggingRef.current = true;
    hoverActiveRef.current = false;
    lastXRef.current = e.clientX;
    lastTRef.current = performance.now();
  };
  const onMouseUp = () => (draggingRef.current = false);

  const onTouchStart = (e) => {
    enterSpinMode();
    const t = e.touches[0];
    draggingRef.current = true;
    lastXRef.current = t.clientX;
    lastTRef.current = performance.now();
  };
  const onTouchMove = (e) => {
    const t = e.touches[0];
    handlePointerMove(t.clientX, t.clientY);
  };
  const onTouchEnd = () => (draggingRef.current = false);

  useEffect(() => {
    const up = () => (draggingRef.current = false);
    window.addEventListener("mouseup", up);
    window.addEventListener("touchend", up);
    return () => {
      window.removeEventListener("mouseup", up);
      window.removeEventListener("touchend", up);
    };
  }, []);

  const goToAngle = (angle) => {
    enterSpinMode();
    hoverActiveRef.current = false;
    draggingRef.current = false;
    targetRef.current = clamp(angle, 0, 90);
  };

  const goToStatic = (key) => {
    setMode("static");
    setStaticKey(key);
  };

  const theta = display.theta; // 0..90
  const rad = (theta * Math.PI) / 180;
  const frac = theta / 90; // 0 at front, 1 at right

  const rotateY = Math.sin(rad) * 24;
  const rotateX = display.tiltX;
  const translateZ = Math.cos(rad) * 26 - 26;
  const scale = 1 + Math.cos(rad) * 0.015;

  const shadowScale = 1 - Math.sin(rad) * 0.12 - (display.bob / 9) * 0.05;
  const shadowOpacity = 0.34 - Math.sin(rad) * 0.08 - Math.max(display.bob, 0) * 0.01;

  const spinFrames = SPIN_FRAMES.map((f) => ({ ...f, label: f.key === "front" ? L.front : L.side }));
  const staticFrames = STATIC_VIEWS.map((v) => ({ ...v, label: v.key === "top" ? L.top : v.key }));
  const allThumbs = [...spinFrames, ...staticFrames];

  return (
    <div
      style={{
        width: "100%",
        minHeight: "100%",
        background: "linear-gradient(180deg, #FFFDF8 0%, #F4EFE6 100%)",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontFamily: "'Mulish', 'Tajawal', sans-serif",
        padding: "40px 16px",
        boxSizing: "border-box",
      }}
    >
      <style>{`
        @keyframes rot360 { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
        @keyframes pulseHint { 0%,100% { opacity: 0.55; } 50% { opacity: 1; } }
        .pv-thumb { transition: transform .22s cubic-bezier(.2,.8,.2,1), box-shadow .22s ease, border-color .22s ease; }
        .pv-thumb:hover:not(.disabled) { transform: translateY(-3px); }
        .pv-thumb.disabled { cursor: default; opacity: 0.5; }
      `}</style>

      <div style={{ width: "100%", maxWidth: 620, display: "flex", flexDirection: "column", alignItems: "center" }}>
        <div style={{ position: "relative", width: "100%" }}>
          <div style={{ position: "absolute", top: 4, left: 0, display: "flex", flexDirection: "column", alignItems: "center", gap: 4 }}>
            <div style={{ position: "relative", width: 46, height: 46 }}>
              <svg width="46" height="46" viewBox="0 0 46 46" style={{ animation: prefersReduced ? "none" : "rot360 6s linear infinite" }}>
                <path d="M23 6 A17 17 0 1 1 6.5 17" fill="none" stroke="#211D18" strokeWidth="2" strokeLinecap="round" />
                <polygon points="23,2 27,8 19,8" fill="#211D18" />
              </svg>
              <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 9, fontWeight: 700, color: "#211D18" }}>
                90°
              </div>
            </div>
          </div>

          <div style={{ position: "absolute", top: 4, right: 0, display: "flex", flexDirection: "column", alignItems: "center", gap: 4, animation: prefersReduced ? "none" : "pulseHint 2.4s ease-in-out infinite" }}>
            <svg width="30" height="30" viewBox="0 0 30 30" fill="none">
              <rect x="10" y="4" width="10" height="16" rx="5" stroke="#6E6557" strokeWidth="1.5" />
              <path d="M6 15 L2 15 M2 15 L5 12 M2 15 L5 18" stroke="#6E6557" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
              <path d="M24 15 L28 15 M28 15 L25 12 M28 15 L25 18" stroke="#6E6557" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
            </svg>
            <div style={{ fontSize: 11, color: "#6E6557", whiteSpace: "nowrap" }}>{L.hint}</div>
          </div>

          <div
            ref={containerRef}
            onMouseMove={onMouseMove}
            onMouseEnter={onMouseEnter}
            onMouseLeave={onMouseLeave}
            onMouseDown={onMouseDown}
            onMouseUp={onMouseUp}
            onTouchStart={onTouchStart}
            onTouchMove={onTouchMove}
            onTouchEnd={onTouchEnd}
            style={{
              position: "relative",
              width: "100%",
              maxWidth: 380,
              margin: "0 auto",
              aspectRatio: "1 / 1.05",
              cursor: draggingRef.current ? "grabbing" : "grab",
              touchAction: "pan-y",
              userSelect: "none",
            }}
          >
            <div style={{ position: "absolute", inset: 0, perspective: "1400px" }}>
              <div
                style={{
                  position: "absolute",
                  inset: 0,
                  transformStyle: "preserve-3d",
                  transform: `translateY(${display.bob}px) rotateX(${rotateX}deg) rotateY(${rotateY}deg) translateZ(${translateZ}px) scale(${scale})`,
                  opacity: 1 - staticOpacity,
                }}
              >
                <img src={IMG_FRONT} alt={L.front} draggable={false}
                  style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "contain", opacity: 1 - frac, filter: "drop-shadow(0 2px 2px rgba(0,0,0,0.06))", pointerEvents: "none" }} />
                <img src={IMG_RIGHT} alt={L.side} draggable={false}
                  style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "contain", opacity: frac, filter: "drop-shadow(0 2px 2px rgba(0,0,0,0.06))", pointerEvents: "none" }} />
              </div>

              <div style={{ position: "absolute", inset: 0, opacity: staticOpacity, pointerEvents: "none", display: "flex", alignItems: "center", justifyContent: "center" }}>
                {(() => {
                  const active = staticFrames.find(v => v.key === staticKey);
                  if (active && active.img) {
                    return (
                      <img src={active.img} alt={active.label} draggable={false}
                        style={{ width: "100%", height: "100%", objectFit: "contain", filter: "drop-shadow(0 2px 2px rgba(0,0,0,0.06))" }} />
                    );
                  }
                  return (
                    <div style={{ textAlign: "center", color: "#6E6557" }}>
                      <svg width="34" height="34" viewBox="0 0 24 24" fill="none" stroke="#c9c2b2" strokeWidth="1.3" style={{ marginBottom: 6 }}>
                        <rect x="3" y="3" width="18" height="18" rx="2" />
                        <circle cx="9" cy="9" r="2" />
                        <path d="M21 15l-5-5L5 21" />
                      </svg>
                      <div style={{ fontSize: 13, letterSpacing: "0.04em" }}>
                        {active ? active.label : ""} · {L.pending}
                      </div>
                    </div>
                  );
                })()}
              </div>
            </div>

            <div style={{ position: "absolute", left: 0, right: 0, top: "62%", height: "38%", overflow: "hidden", pointerEvents: "none", WebkitMaskImage: "linear-gradient(to bottom, rgba(0,0,0,0.22), transparent 78%)", maskImage: "linear-gradient(to bottom, rgba(0,0,0,0.22), transparent 78%)", opacity: 0.5 * (1 - staticOpacity) }}>
              <div style={{ position: "absolute", left: 0, right: 0, top: "-100%", height: "100%", transform: `scaleY(-1) translateY(${-display.bob}px) rotateY(${rotateY}deg)`, transformOrigin: "top center" }}>
                <img src={IMG_FRONT} alt="" draggable={false} style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "contain", objectPosition: "center top", opacity: 1 - frac }} />
                <img src={IMG_RIGHT} alt="" draggable={false} style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "contain", objectPosition: "center top", opacity: frac }} />
              </div>
            </div>

            <div style={{ position: "absolute", left: "50%", bottom: "10%", width: "46%", height: "7%", background: "#1a1a1a", borderRadius: "50%", filter: "blur(14px)", opacity: shadowOpacity, transform: `translateX(-50%) scale(${shadowScale})`, pointerEvents: "none" }} />
          </div>

          <div style={{ display: "flex", justifyContent: "center", marginTop: -8 }}>
            <svg width="220" height="34" viewBox="0 0 220 34">
              <path d="M10 8 C 60 34, 160 34, 210 8" fill="none" stroke="#c9c2b2" strokeWidth="1.5" strokeDasharray="1 6" strokeLinecap="round" />
              <path d="M10 8 L16 5 M10 8 L15 12" stroke="#c9c2b2" strokeWidth="1.5" strokeLinecap="round" fill="none" />
              <path d="M210 8 L204 5 M210 8 L205 12" stroke="#c9c2b2" strokeWidth="1.5" strokeLinecap="round" fill="none" />
            </svg>
          </div>
          <div style={{ textAlign: "center", fontSize: 12, color: "#6E6557", letterSpacing: "0.08em", marginTop: -6 }}>{L.range}</div>
        </div>

        <div style={{ display: "flex", gap: 10, marginTop: 22, flexWrap: "wrap", justifyContent: "center" }}>
          {allThumbs.map((t) => {
            const isSpin = "angle" in t;
            const isActive = isSpin ? display.activeLabel === t.label && mode === "spin" : mode === "static" && staticKey === t.key;
            const hasImg = isSpin || t.img;
            if (!hasImg) return null;
            return (
              <button
                key={t.label}
                className={`pv-thumb${hasImg ? "" : " disabled"}`}
                onClick={() => (isSpin ? goToAngle(t.angle) : hasImg && goToStatic(t.key))}
                disabled={!hasImg}
                style={{ width: 68, display: "flex", flexDirection: "column", alignItems: "center", gap: 6, background: "transparent", border: "none", cursor: hasImg ? "pointer" : "default", padding: 0 }}
              >
                <div style={{
                  width: 60, height: 60, borderRadius: 12,
                  border: isActive ? "2px solid #B99244" : "1px solid #e4ddce",
                  background: "#FFFDF8",
                  boxShadow: isActive ? "0 6px 16px rgba(185,146,68,0.22)" : "0 2px 6px rgba(0,0,0,0.04)",
                  padding: 6, display: "flex", alignItems: "center", justifyContent: "center",
                }}>
                  {hasImg ? (
                    <img src={t.img} alt={t.label} draggable={false} style={{ width: "100%", height: "100%", objectFit: "contain" }} />
                  ) : (
                    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#c9c2b2" strokeWidth="1.5">
                      <rect x="3" y="3" width="18" height="18" rx="2" />
                      <circle cx="9" cy="9" r="2" />
                      <path d="M21 15l-5-5L5 21" />
                    </svg>
                  )}
                </div>
                <div style={{ fontSize: 10.5, color: isActive ? "#211D18" : "#6E6557", textAlign: "center", lineHeight: 1.2 }}>
                  {t.label}
                </div>
              </button>
            );
          })}
        </div>

        <div style={{ marginTop: 16, fontSize: 12, color: "#6E6557", textAlign: "center", maxWidth: 420, lineHeight: 1.5 }}>
          {L.caption}
        </div>
      </div>
    </div>
  );
}
